?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>BI Action Center - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><link rel="stylesheet" href="assets/bi_step22.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="executive_bi.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>STEP 22 • Management Action Center</small></span></a><div class="os-top-actions"><a class="os-btn" href="notification_inbox.php">Notifications</a><a class="os-btn primary" href="executive_bi.php">Executive BI</a></div></div></header><main class="os-main" style="max-width:1450px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">FACT-BASED ACTION QUEUE</div><h1>Turn operational conditions into explicit management follow-through.</h1><p>No predictive score is invented. Every signal links back to a real operational source and remains visible while its underlying condition still exists.</p></section><?php if($error):?><div class="pp-alert bad"><?=bi_step22_h($error)?></div><?php endif;?><?php if($msg):?><div class="pp-alert good"><?=bi_step22_h($msg)?></div><?php endif;?><?php if(!$error):?><section class="bi-grid" style="margin-top:14px"><article class="os-card bi-span-8"><div class="os-title-row"><div><h2>Current Signals</h2><p><?=count($signals)?> active condition(s).</p></div></div><?php if(!$signals):?><div class="bi-note"><b>No current action signal.</b><small class="bi-muted">This means no configured fact condition is currently active.</small></div><?php endif;?><?php foreach($signals as $s):?><div class="bi-signal <?=bi_step22_h($s['severity'])?>"><div style="min-width:0"><b><?=bi_step22_h($s['title'])?></b><small><?=bi_step22_h($s['detail'])?></small><div class="bi-pills" style="margin-top:7px"><span class="bi-pill"><?=bi_step22_h(strtoupper($s['severity']))?></span><span class="bi-pill"><?=bi_step22_h(strtoupper($s['workflow_status']))?></span><a class="bi-pill" href="<?=bi_step22_h($s['url'])?>">Open Source →</a></div><?php if($s['workflow_note']):?><small><?=bi_step22_h($s['workflow_note'])?></small><?php endif;?></div><form method="post" style="display:grid;gap:6px;min-width:210px"><input type="hidden" name="action" value="signal"><input type="hidden" name="signal_key" value="<?=bi_step22_h($s['key'])?>"><input type="hidden" name="signal_type" value="<?=bi_step22_h($s['type'])?>"><select name="status" style="padding:7px;border:1px solid #d8dfda;border-radius:8px"><option value="acknowledged">Acknowledge</option><option value="resolved">Mark action resolved</option></select><input name="note" placeholder="Optional action note" style="padding:7px;border:1px solid #d8dfda;border-radius:8px"><button class="os-btn">Update</button></form></div><?php endforeach;?></article><article class="os-card bi-span-4"><div class="os-title-row"><div><h2>Add Executive Note</h2><p>Management context stays separate from source facts.</p></div></div><form method="post" class="bi-form"><input type="hidden" name="action" value="note"><div class="bi-field full"><label>Date</label><input type="date" name="note_date" value="<?=date('Y-m-d')?>"></div><div class="bi-field full"><label>Title</label><input name="title" maxlength="190" required></div><div class="bi-field full"><label>Note</label><textarea name="note_text" rows="5" required></textarea></div><div class="bi-field full"><button class="os-btn primary">Add Note</button></div></form></article><article class="os-card bi-span-12"><div class="os-title-row"><div><h2>Executive Notes</h2><p>Notes do not alter KPI source data.</p></div></div><?php if(!$notes):?><div class="bi-note">No executive notes yet.</div><?php endif;?><?php foreach($notes as $n):?><div class="bi-note"><b><?=bi_step22_h($n['title'])?></b><small class="bi-muted"><?=bi_step22_h($n['note_date'])?><?=!empty($n['full_name'])?' • '.bi_step22_h($n['full_name']):''?></small><p style="margin:7px 0 0"><?=nl2br(bi_step22_h($n['note_text']))?></p></div><?php endforeach;?></article></section><?php endif;?></main></body></html>